// adaptive_bar: fold pinned tray icons first, then shrink both centre side
// groups, whenever the right section would spill over the centred middle
// section; clip only what still cannot fit.
AdaptiveBar.FitController {
    id: adaptiveBarFit
    barWidth: root.width
    stockSideWidth: root.centerSideModuleWidth
    middle: middleSection
    leftSide: leftCenterGroup
    rightSide: rightCenterGroup
    rightContent: rightCenterGroupContent
    rightRow: rightSectionRowLayout
    tray: adaptiveBarTray
}
Binding {
    target: leftCenterGroup
    property: "implicitWidth"
    value: adaptiveBarFit.side
}
Binding {
    target: rightCenterGroup
    property: "implicitWidth"
    value: adaptiveBarFit.side
}
Binding {
    target: barRightSideMouseArea
    property: "clip"
    value: adaptiveBarFit.overflow > 0
}

// adaptive_bar: the horizontal bar folds the first N pinned icons into the
// overflow menu while it is short on space (0 keeps the stock tray).
property int adaptiveBarFoldCount: 0
readonly property int adaptiveBarFolded: Math.max(0, Math.min(root.adaptiveBarFoldCount, root.pinnedItems.length))
readonly property var adaptiveBarOverflowItems: {
    const items = [];
    for (let i = 0; i < root.adaptiveBarFolded; i++)
        items.push(root.pinnedItems[i]);
    for (let i = 0; i < root.unpinnedItems.length; i++)
        items.push(root.unpinnedItems[i]);
    return items;
}
// Width freed per folded icon: stock SysTrayItem (20 px) plus one grid gap.
readonly property real adaptiveBarFoldUnit: 20 + gridLayout.columnSpacing
// Folding reveals the overflow button when nothing is unpinned.
readonly property real adaptiveBarOverflowOverhead: root.showOverflowMenu && root.unpinnedItems.length === 0 ? trayOverflowButton.implicitWidth + gridLayout.columnSpacing : 0
Binding {
    target: trayOverflowButton
    property: "visible"
    value: root.showOverflowMenu && root.adaptiveBarOverflowItems.length > 0
    when: root.adaptiveBarFolded > 0
}
Binding {
    target: overflowPopup
    property: "active"
    value: root.trayOverflowOpen && root.adaptiveBarOverflowItems.length > 0
    when: root.adaptiveBarFolded > 0
}

Binding {
    target: adaptiveBarOverflowRepeater
    property: "model"
    value: root.adaptiveBarOverflowItems
    when: root.adaptiveBarFolded > 0
}
Binding {
    target: trayOverflowLayout
    property: "columns"
    value: Math.ceil(Math.sqrt(root.adaptiveBarOverflowItems.length))
    when: root.adaptiveBarFolded > 0
}
